// Digest every untracked, unignored path in a worktree: name, type, mode, and
// either the file's bytes or the symlink's target (never the target's contents).
// Stands in for the tar pipeline, which is outside the issue-stage Bash allowance.
import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { lstatSync, readFileSync, readlinkSync } from 'node:fs'
import { join } from 'node:path'

const wt = process.argv[2]
if (!wt) {
  console.error('usage: untracked-digest.mjs <worktree>')
  process.exit(2)
}

const raw = execFileSync('git', ['-C', wt, 'ls-files', '--others', '--exclude-standard', '-z'])
const paths = raw.toString('utf8').split('\0').filter(Boolean).sort()

const h = createHash('sha256')
for (const p of paths) {
  const abs = join(wt, p)
  const st = lstatSync(abs)
  const type = st.isSymbolicLink() ? 'l' : st.isDirectory() ? 'd' : 'f'
  h.update(p, 'utf8')
  h.update('\0')
  h.update(`${type}:${(st.mode & 0o7777).toString(8)}`)
  h.update('\0')
  if (type === 'l') h.update(readlinkSync(abs), 'utf8')
  else if (type === 'f') h.update(readFileSync(abs))
  h.update('\0')
}

console.log(`${h.digest('hex')}  ${paths.length} untracked path(s)`)

